INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36611, 'Ephesians 1:15', 'Ephesians', 1, 15, 'له دې امله کله چې زه ستاسو د ایمان نه چې په څښتن عیسی باندې یې لرئ او د هغې مینې نه چې د خدای د ټولو خلکو سره یې کوئ، خبر شوم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_15.mp3', '', 1761754199, 1761754199),
(36612, 'Ephesians 1:16', 'Ephesians', 1, 16, 'نو ستاسو په خاطر مې خدای ته شکر کول پرېنښودل او تاسو تل په خپلو دعاګانو کې یادوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_16.mp3', '', 1761754199, 1761754199),
(36613, 'Ephesians 1:17', 'Ephesians', 1, 17, 'زه د څښتن عیسی مسیح د خدای څخه چې د جلال نه ډک پلار دی، غواړم چې هغه تاسو ته د حکمت او مکاشفې روح درکړي، ترڅو هغه په ښه توګه وپېژنئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_17.mp3', '', 1761754199, 1761754199),
(36614, 'Ephesians 1:18', 'Ephesians', 1, 18, 'زه دعا کوم چې ستاسو د زړونو سترګې دې روښانه شي، ترڅو په دې پوه شئ چې هغه تاسو په کومې هیلې سره رابللي یئ یعنې هغه پرېمانه او شانداره میراث ته چې هغه خپلو خلکو ته ساتلی دی،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_18.mp3', '', 1761754199, 1761754199),
(36615, 'Ephesians 1:19', 'Ephesians', 1, 19, 'او په دې هم پوه شئ چې زمونږ ایماندارانو دپاره د هغه قدرت څومره بې‌حده او ډېر لوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_19.mp3', '', 1761754199, 1761754199),
(36616, 'Ephesians 1:20', 'Ephesians', 1, 20, 'دا هماغه لوی قدرت دی چې هغه ترې کار واخیست کله چې مسیح یې د مړو نه بېرته راژوندی کړ او په اسماني ځایونو کې یې خپل ښي لاس ته کښېناوه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_20.mp3', '', 1761754199, 1761754199),
(36617, 'Ephesians 1:21', 'Ephesians', 1, 21, 'او هغه یې د هر حکومت، د واک خاوند، هر قدرت او بل هر لوړ مقام نه چې کولای شو نوم یې واخلو اوچت کړ، یوازې په دې دنیا کې نه بلکې په راتلونکې دنیا کې هم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_21.mp3', '', 1761754199, 1761754199),
(36618, 'Ephesians 1:22', 'Ephesians', 1, 22, 'خدای ټول شیان د مسیح په اختیار کې ورکړل او هغه یې د کلیسا دپاره د ټولو شیانو سر کړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_22.mp3', '', 1761754199, 1761754199),
(36619, 'Ephesians 1:23', 'Ephesians', 1, 23, 'او کلیسا د مسیح بدن دی چې په خپله د مسیح په وسیله کامل کیږي او په همدې وخت کې کاینات د خپل حضور نه ډکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_23.mp3', '', 1761754199, 1761754199),
(36620, 'Hebrews 8:1', 'Hebrews', 8, 1, 'اوس چې مونږ کومې خبرې کوو په هغو کې مهم ټکی دا دی چې مونږ یو داسې لوی کاهن لرو چې په اسمانونو کې د مطلق قادر خدای د تخت ښي لاس ته ناست دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_1.mp3', '', 1761754199, 1761754199),
(36621, 'Hebrews 8:2', 'Hebrews', 8, 2, 'هغه په هغه سپېڅلي ځای او هغې حقیقي خېمه کې خدمت کوي چې د څښتن له خوا جوړه شوې ده، نه د انسان په لاس.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_2.mp3', '', 1761754199, 1761754199),
(36622, 'Hebrews 8:3', 'Hebrews', 8, 3, 'څرنګه چې هر لوی کاهن د دې دپاره ټاکل شوی دی چې خدای ته نذرانې او قربانۍ وړاندې کړي، نو زمونږ د لوی کاهن سره هم باید د ورکولو دپاره یو څه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_3.mp3', '', 1761754199, 1761754199),
(36623, 'Hebrews 8:4', 'Hebrews', 8, 4, 'که چېرې عیسی لا تر‌اوسه هم د ځمکې په مخ ژوند کولای، نو هغه به کاهن نه وای، ځکه چې نور کاهنان هم شته چې د شریعت له مخې نذرانې وړاندې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_4.mp3', '', 1761754199, 1761754199),
(36624, 'Hebrews 8:5', 'Hebrews', 8, 5, 'هغوی چې په سپېڅلي ځای کې کوم خدمت کوي، هغه یوازې یوه نمونه او د اسماني شیانو یو تصویر دی. ځکه کله چې موسی غوښتل خېمه جوړه کړي، نو هغه ته د خدای له خوا لارښوونه وشوه: «پام کوه چې هرڅه د هغې نمونې له مخې جوړ کړې چې د غره په سر باندې مې درته وښودله.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_5.mp3', '', 1761754199, 1761754199),
(36625, 'Hebrews 8:6', 'Hebrews', 8, 6, 'خو عیسی ته چې کوم کار ورسپارل شوی ؤ چې د کاهن په توګه خدمت وکړي، هغه د هغو کارونو نه ډېر مهم دی چې هغوی کول، ځکه چې دا لوظ چې هغه د خدای او انسان ترمنځ منځګړتوب کوي ډېر ښه دی او له مخکې نه په ډېرو ښو وعدو باندې ولاړ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_6.mp3', '', 1761754199, 1761754199),
(36626, 'Hebrews 8:7', 'Hebrews', 8, 7, 'که چېرې په لومړني لوظ کې کوم عیب نه وای، نو دوهم لوظ ته به اړتیا نه وای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_7.mp3', '', 1761754199, 1761754199),
(36627, 'Hebrews 8:8', 'Hebrews', 8, 8, 'خو کله چې خدای په خپل قوم کې غلطي پیدا کړه، نو داسې یې وویل: څښتن وایي: «هغه ورځ به رارسیږي کله چې د اسراییلو او یهودا د خلکو سره نوی لوظ وکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_8.mp3', '', 1761754199, 1761754199),
(36628, 'Hebrews 8:9', 'Hebrews', 8, 9, 'خو دا لوظ به د هغه لوظ په شان نه وي چې د هغوی د نیکونو سره مې کړی ؤ. په هغه ورځ چې ما د هغوی لاسونه ونیول او د مصر څخه مې راوویستل، ځکه چې هغوی زما لوظ ته وفادار پاتې نه شول.» څښتن وایي: «نو بیا ما خپل مخ له هغوی هم واړاوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_9.mp3', '', 1761754199, 1761754199),
(36629, 'Hebrews 8:10', 'Hebrews', 8, 10, 'او همدارنګه څښتن وایي: «دا هغه لوظ دی چې زه به یې په راتلونکې کې د اسراییلو د خلکو سره وکړم. زه به خپل شریعت د هغوی په ذهنونو کې واچوم او د هغوی په زړونو کې به یې ولیکم. زه به د هغوی خدای یم او هغوی به زما قوم وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_10.mp3', '', 1761754199, 1761754199),
(36630, 'Hebrews 8:11', 'Hebrews', 8, 11, 'نور به هغوی خپل ګاونډي او ورور ته دا تعلیم نه ورکوي او ورته به نه وایي: ‹څښتن وپېژنه،› ځکه چې لوی او واړه ټول به ما پېژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_11.mp3', '', 1761754199, 1761754199),
(36631, 'Hebrews 8:12', 'Hebrews', 8, 12, 'نو زه به د هغوی بدۍ او خطاګانې وبخښم او نور به د هغوی ګناهونه نه یادوم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_12.mp3', '', 1761754199, 1761754199),
(36632, 'Hebrews 8:13', 'Hebrews', 8, 13, 'کله چې خدای د نوي لوظ په هکله خبرې کوي، نو لومړنی لوظ باطلوي او کوم شی چې باطل او زوړ شي هغه زر له منځه ځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews8_verse_13.mp3', '', 1761754199, 1761754199),
(36633, 'Matthew 8:1', 'Matthew', 8, 1, 'کله چې عیسی د غره نه راښکته شو، نو ګڼ شمېر خلک ورپسې روان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_1.mp3', '', 1761754199, 1761754199),
(36634, 'Matthew 8:2', 'Matthew', 8, 2, 'په دې وخت کې یو جذامي سړی هغه ته راغی او د هغه په پښو کې پرېوت او ویې ویل: «ښاغلیه، که ته وغواړې نو کولای شې چې ما پاک او روغ کړې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_2.mp3', '', 1761754199, 1761754199),
(36635, 'Matthew 8:3', 'Matthew', 8, 3, 'عیسی خپل لاس وراوږد کړ او په هغه باندې یې کېښود او ویې ویل: «زه غواړم، پاک او روغ شه» او هغه سمدلاسه د جذام څخه پاک او روغ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_3.mp3', '', 1761754199, 1761754199),
(36636, 'Matthew 8:4', 'Matthew', 8, 4, 'بیا عیسی هغه ته وویل: «ګوره چې په دې هکله هېچا ته څه ونه وایې، خو لاړ شه او خپل ځان کاهن ته وروښایه او کومه قرباني چې موسی یې حکم کړی دی وړاندې کړه، د دې دپاره چې خلکو ته ثابته شي چې ته روغ شوی یې.» عیسی د رومي منصبدار نوکر ته شفا ورکوي (لوقا ۷‏:‌۱‌‏-‌۱۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_4.mp3', '', 1761754199, 1761754199),
(36637, 'Matthew 8:5', 'Matthew', 8, 5, 'کله چې عیسی د کپرناحوم ښار ته ورغی، نو یو رومي منصبدار ورته راغی او هغه ته یې زاري وکړه،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_5.mp3', '', 1761754199, 1761754199),
(36638, 'Matthew 8:6', 'Matthew', 8, 6, 'او ورته ویې ویل: «ای ښاغلیه، زما یو نوکر په کور کې شل پروت دی او ډېر په عذاب دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_6.mp3', '', 1761754199, 1761754199),
(36639, 'Matthew 8:7', 'Matthew', 8, 7, 'عیسی وویل: «زه به درشم او هغه به روغ کړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_7.mp3', '', 1761754199, 1761754199),
(36640, 'Matthew 8:8', 'Matthew', 8, 8, 'خو هغه منصبدار ورته په ځواب کې وویل: «ای ښاغلیه، زه د دې لایق نه یم چې زما کور ته راشې. ته یوازې امر وکړه، نو زما نوکر به روغ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_8.mp3', '', 1761754199, 1761754199),
(36641, 'Matthew 8:9', 'Matthew', 8, 9, 'ځکه چې زه هم د بل چا د امر لاندې یم او عسکر زما د امر لاندې دي. کله چې یو ته ووایم چې لاړ شه، نو هغه ځي او بل ته ووایم چې راشه نو هغه راځي او کله چې خپل نوکر ته ووایم چې دا کار وکړه نو هغه یې کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_9.mp3', '', 1761754199, 1761754199),
(36642, 'Matthew 8:10', 'Matthew', 8, 10, 'کله چې عیسی د هغه خبرې واورېدلې نو حیران شو او کوم خلک چې په هغه پسې روان وو، هغوی ته یې وویل: «په یقین سره زه تاسو ته دا وایم چې ما داسې ایمان په اسراییلو کې هم نه دی لیدلی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_10.mp3', '', 1761754199, 1761754199),
(36643, 'Matthew 8:11', 'Matthew', 8, 11, 'زه تاسو ته وایم چې د ختیځ او لوېدیځ څخه به ډېر خلک راشي او د ابراهیم، اسحاق او یعقوب سره به د اسماني پاچاهۍ په مېلمستیا کې کښېني،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_11.mp3', '', 1761754199, 1761754199),
(36644, 'Matthew 8:12', 'Matthew', 8, 12, 'خو کوم خلک چې د دې پاچاهۍ دپاره ټاکل شوي وو هغوی به دباندې تیارو ته یعنې هغه ځای ته وغورځول شي چې هلته به خلک ژاړي او خپل غاښونه به چیچي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_12.mp3', '', 1761754199, 1761754199),
(36645, 'Matthew 8:13', 'Matthew', 8, 13, 'بیا عیسی هغه منصبدار ته وویل: «بېرته خپل کور ته لاړ شه، لکه څنګه چې باور لرې همداسې به وشي.» نو په هماغه ساعت هغه نوکر روغ شو. عیسی ډېرو خلکو ته شفا ورکوي (مرقوس ۱‏:‌۲۹‌‏-‌۳۴ او لوقا ۴‏:‌۳۸‌‏-‌۴۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_13.mp3', '', 1761754199, 1761754199),
(36646, 'Matthew 8:14', 'Matthew', 8, 14, 'کله چې عیسی د پطروس کور ته ورغی، نو ویې لیدل چې د پطروس خواښې د تبې له لاسه پرته وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_14.mp3', '', 1761754199, 1761754199),
(36647, 'Matthew 8:15', 'Matthew', 8, 15, 'عیسی د هغې لاس ونیوه او تبې هغه پرېښودله. هغه راپاڅېدله او د عیسی خدمت یې پیل کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_15.mp3', '', 1761754199, 1761754199),
(36648, 'Matthew 8:16', 'Matthew', 8, 16, 'کله چې ماښام شو، نو خلکو هغه ته ډېر داسې کسان راوستل چې پېریانو نیولي وو او په یو حکم یې د هغوی څخه پېریان وویستل او ټول ناروغان یې روغ کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_16.mp3', '', 1761754199, 1761754199),
(36649, 'Matthew 8:17', 'Matthew', 8, 17, 'په دې ډول د اشعیا نبي هغه وینا رښتیا شوه چې ویلي یې وو: هغه زمونږ ټولې ناروغۍ لېرې کړلې، او زمونږ کمزورۍ یې لېرې کړلې. د عیسی څخه د پیروۍ کولو بیه (لوقا ۹‏:‌۵۷‌‏-‌۶۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_17.mp3', '', 1761754199, 1761754199),
(36650, 'Matthew 8:18', 'Matthew', 8, 18, 'کله چې عیسی ولیدل چې د خلکو ګڼه‌ګوڼه ورڅخه راچاپېره ده نو خپلو شاګردانو ته یې حکم وکړ چې د جلیل د بحیرې بلې غاړې ته لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_18.mp3', '', 1761754199, 1761754199),
(36651, 'Matthew 8:19', 'Matthew', 8, 19, 'د شریعت یو عالم هغه ته ورغی او ویې ویل: «استاذه! هر‌چېرته چې ځې زه به درپسې ځم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_19.mp3', '', 1761754199, 1761754199),
(36652, 'Matthew 8:20', 'Matthew', 8, 20, 'عیسی ورته وویل: «ګیدړان خپل غارونه لري او مرغان خپلې ځالې، خو د انسان زوی دومره ځای هم نه لري چې خپل سر ورباندې کېږدي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_20.mp3', '', 1761754199, 1761754199),
(36653, 'Matthew 8:21', 'Matthew', 8, 21, 'یو بل شاګرد ورته وویل: «استاذه، اجازه راکړه چې لومړی لاړ شم او خپل پلار خاورو ته وسپارم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_21.mp3', '', 1761754199, 1761754199),
(36654, 'Matthew 8:22', 'Matthew', 8, 22, 'عیسی ځواب ورکړ: «ته ما پسې راځه او پرېږده چې مړي خپل مړي ښخ کړي.» عیسی توفان اراموي (مرقوس ۴‏:‌۳۵‌‏-‌۴۱ او لوقا ۸‏:‌۲۲‌‏-‌۲۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew8_verse_22.mp3', '', 1761754199, 1761754199),
