(36697, 'Acts 3:20', 'Acts', 3, 20, 'بیا به داسې وختونه راشي چې څښتن تاسو ته روحاني سکون درکړي. خدای به تاسو ته عیسی چې ستاسو دپاره ټاکل شوی مسیح دی، درولېږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts3_verse_20.mp3', '', 1761754199, 1761754199),
(36698, 'Acts 3:21', 'Acts', 3, 21, 'لکه څنګه چې خدای د خپلو سپېڅلو پیغمبرانو په وسیله ډېر پخوا وعده کړې وه، عیسی باید تر هغه وخته پورې په اسمان کې پاتې شي، ترڅو ټول شیان بېرته جوړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts3_verse_21.mp3', '', 1761754199, 1761754199),
(36699, 'Acts 3:22', 'Acts', 3, 22, 'ځکه چې موسی وویل: ‹ستاسو څښتن خدای به ستاسو د خپل قوم څخه زما په شان یو پیغمبر درولېږي. هغه چې هرڅه وایي تاسو به ورته غوږ نیسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts3_verse_22.mp3', '', 1761754199, 1761754199),
(36700, 'Acts 3:23', 'Acts', 3, 23, 'هرڅوک چې د هغه پیغمبر خبرو ته غوږ ونه نیسي او هغه ونه مني، نو هغه به د خدای د قوم څخه وویستل شي او له منځه به یووړل شي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts3_verse_23.mp3', '', 1761754199, 1761754199),
(36701, 'Acts 3:24', 'Acts', 3, 24, 'سموییل او نورو ټولو پیغمبرانو چې د هغه څخه وروسته راغلي دي په دې هکله خبرې کړې وې چې په دې ورځو کې به څه وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts3_verse_24.mp3', '', 1761754199, 1761754199),
(36702, 'Acts 3:25', 'Acts', 3, 25, 'تاسو د پیغمبرانو وارثان یئ او په هغه لوظ کې شریک یئ چې خدای ستاسو د نیکونو سره کړی دی، لکه څنګه چې خدای ابراهیم ته وویل: ‹ستا د اولادې په وسیله به د نړۍ ټول خلک برکت ومومي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts3_verse_25.mp3', '', 1761754199, 1761754199),
(36703, 'Acts 3:26', 'Acts', 3, 26, 'کله چې خدای خپل خدمتګار عیسی وټاکه، نو هغه یې اول تاسو ته درولېږه چې تاسو هر یو د خپلو بدو لارو څخه راواړوي او برکت درته درکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts3_verse_26.mp3', '', 1761754199, 1761754199),
(36704, 'Galatians 3:1', 'Galatians', 3, 1, 'ای ناپوهه غلاتیانو ایماندارانو! تاسو ته په ښکاره وویل شول چې عیسی مسیح څنګه په صلیب ځوړند کړای شو. نو بیا په تاسو باندې چا جادو کړې ده چې دا نه منئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_1.mp3', '', 1761754199, 1761754199),
(36705, 'Galatians 3:2', 'Galatians', 3, 2, 'زه یوازې غواړم په دې پوه شم چې: ایا تاسو په شریعت باندې په عمل کولو سره روح القدس تر‌لاسه کړ یا مو د زېري په اورېدلو او په هغه باندې د ایمان راوړلو له لارې؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_2.mp3', '', 1761754199, 1761754199),
(36706, 'Galatians 3:3', 'Galatians', 3, 3, 'بیا څنګه کېدای شي چې دومره ناپوهه اوسئ؟ تاسو چې خپل نوی ژوند د روح القدس په وسیله پیل کړ، اوس غواړئ چې په خپل انساني کوښښ یې کامل کړئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_3.mp3', '', 1761754199, 1761754199),
(36707, 'Galatians 3:4', 'Galatians', 3, 4, 'ایا ستاسو د ژوند ټولې تجربې بې‌ګټې وې؟ په یقین سره چې بې‌ګټې نه وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_4.mp3', '', 1761754199, 1761754199),
(36708, 'Galatians 3:5', 'Galatians', 3, 5, 'ایا خدای چې تاسو ته روح القدس درکوي او معجزې درښایي، دا په شریعت باندې د عمل کولو په خاطر دی که د مسیح د زېري اورېدلو او په هغه باندې د ایمان راوړلو له امله؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_5.mp3', '', 1761754199, 1761754199),
(36709, 'Galatians 3:6', 'Galatians', 3, 6, 'د ابراهیم په هکله فکر وکړئ: «ابراهیم په خدای ایمان راوړ او خدای هغه د خپل ایمان له امله عادل وګاڼه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_6.mp3', '', 1761754199, 1761754199),
(36710, 'Galatians 3:7', 'Galatians', 3, 7, 'نو بیا پوه شئ چې د ابراهیم رښتیني اولادونه هغه خلک دي چې په خدای ایمان لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_7.mp3', '', 1761754199, 1761754199);